"""Audit pinned public reference labels; no model calls, no human annotation."""
import collections,hashlib,json,re
from pathlib import Path
BASE=Path(__file__).resolve().parents[1];DATA=BASE/'data/reference-audit';ROOT=DATA/'clef/2019-TAR'
SPECS=[('Training','CD012347'),('Testing','CD010558'),('Testing','CD010753')]

def main():
 records=[];pools={}
 for split,q in SPECS:
  p=ROOT/f'Task2/{split}/Intervention/topics/{q}';raw=p.read_text();title=re.search(r'Title:\s*(.*?)\s*Query:',raw,re.S).group(1).strip()
  ids=re.findall(r'^\s*(\d+)\s*$',raw.split('Pids:')[-1],re.M);assert len(ids)==len(set(ids));pools[q]=set(ids)
  labels={}
  for kind in ['abs','content']:
   f=next((ROOT/f'Task2/{split}/Intervention/qrels').glob('*.'+kind+'.2019.qrels'));labels[kind]={}
   for line in f.read_text().splitlines():
    topic,_,doc,grade=line.split()
    if topic==q:
     assert doc not in labels[kind];assert int(grade) in [0,1];labels[kind][doc]=int(grade)
   assert set(labels[kind])==set(ids)
  objective=(ROOT/f'Task1/{split}/Intervention/topics/{q}').read_text().split('Objective:')[-1].strip()
  record={'topic_id':q,'original_split':split,'title':title,'objective':objective,'candidate_count':len(ids),'abstract_positive':sum(labels['abs'].values()),'content_positive':sum(labels['content'].values()),'abstract_positive_content_negative':sum(labels['abs'][d]==1 and labels['content'][d]==0 for d in ids),'content_positive_abstract_negative':sum(labels['abs'][d]==0 and labels['content'][d]==1 for d in ids),'labels':[{'pmid':d,'abstract_label':labels['abs'][d],'content_label':labels['content'][d]} for d in ids]}
  records.append(record)
 overlaps={a+'__'+b:sorted(pools[a]&pools[b]) for i,a in enumerate(pools) for b in list(pools)[i+1:]}
 files={str(p.relative_to(DATA)):hashlib.sha256(p.read_bytes()).hexdigest() for p in DATA.rglob('*') if p.is_file() and p.suffix not in ['.csv'] and p.name not in ['clinical-reference-audit.json']}
 output={'status':'metadata_and_label_audit_not_pipeline_evaluation','clef_commit':json.loads((DATA/'clef-tree.json').read_text())['sha'],'synergy_commit':json.loads((DATA/'synergy-tree.json').read_text())['sha'],'selection_rule':'clinical intervention topic applicability, selected before any SciSpark model outputs; not selected by benchmark performance','topics':records,'cross_topic_pmid_overlap':overlaps,'source_hashes':files}
 (BASE/'data_manifest/clinical-reference-audit.json').write_text(json.dumps(output,indent=2))
 lines=['# Clinical reference-data audit','','Status: metadata and label audit only. The production clinical matcher, query planner and judge have not yet been evaluated on these topics. No new annotations or paid calls.','','## CLEF TAR intervention shortlist','','| Original split | Topic | Subject | Candidate records | Abstract-positive | Final-content-positive | Abstract-positive/content-negative |','|---|---|---|---:|---:|---:|---:|']
 for r in records:lines.append(f"| {r['original_split']} | {r['topic_id']} | {r['title']} | {r['candidate_count']} | {r['abstract_positive']} | {r['content_positive']} | {r['abstract_positive_content_negative']} |")
 lines+=['','Every shortlisted PMID has one binary abstract label and one binary content label, with no duplicate topic-PMID rows. Content-positive/abstract-negative count is zero in these three pools. These are record counts, not necessarily unique studies.','','## Why this is a useful next step','','CLEF Task2 supplies an expert Boolean-search candidate pool and separate screening labels; it tests screening/ranking within that pool, not discovery of everything outside it. Task1 supplies review title/objective information for retrieval. The three downloaded Task1 protocols are brief objectives rather than complete operational eligibility specifications. Expert search strings are retained for audit but must not be supplied to an autonomous planner and then scored as if it independently produced them.','','Keep the original Training topic as development and the two Testing topics as a provisional validation cohort. This is only three topics and cannot support broad clinical validation. Cross-topic document overlaps exist:']
 for k,v in overlaps.items():lines.append(f'- {k}: {len(v)} shared PMIDs.')
 lines+=['','For judge prompt fitting, remove or group development-overlap documents before creating validation examples and report the altered denominator; retain complete original pools for faithful benchmark reporting. Do not hide the shared test-topic documents or bootstrap every record as independent.','','## Label compatibility with the actual Psychiatry product','','The existing clinical feed matches watch facets and includes treatment, safety and other research. It is not a systematic-review eligibility screener. A review label0 does not automatically mean the paper should be excluded from a clinician feed. Full-text-only exclusions are especially unsuitable as hard abstract-level negatives.','','First executable clinical task: freeze a watch configuration from each objective, using the actual clinical taxonomy and exposing any unsupported concept mapping. Fetch and freeze candidate title/abstract metadata. Run the unchanged clinical stages and report retention of abstract-positive records, final-content-positive retention as a secondary coverage metric, stage-specific losses, ungraded status and candidate reduction. Do not call label0 feed outputs false positives without a compatible target definition. A review-eligibility adapter with full criteria would be a separate experimental system.','','Watch mapping risks: TRD is a narrower population than depression; psychotherapy and antidepressants are broad treatment families; depression with COPD needs the conjunction of two conditions. Verify these mappings before calls. Do not inject paper-specific answers learned from qrels into watch entries.','','## SYNERGY alternatives','','The pinned catalog identifies three relevant candidates:','- Oud_2018: adult borderline-personality-disorder specialized psychotherapy trials; detailed criteria include treatment duration and intervention completeness. Strong clinical-intervention candidate, but these restrictions exceed a simple disease/treatment watch entry.','- van_Dis_2020: longer-term CBT outcomes across anxiety-related disorders, with specific population/comparator exclusions. Potential second intervention dataset after label-stage and metadata audit.','- Brouwer_2019: prospective predictors of depression relapse/recurrence. Useful for other-research matching; not a treatment-effect benchmark.','','Only catalog eligibility information has been audited for SYNERGY; its per-record labels/text availability and source provenance are not yet verified. Do not substitute this metadata audit for dataset readiness.','','## Sources and reproducibility','',f"- CLEF TAR pinned revision: `{output['clef_commit']}`; [Task2 documentation](https://github.com/CLEF-TAR/tar/blob/{output['clef_commit']}/2019-TAR/Task2/README.md).",f"- SYNERGY pinned revision: `{output['synergy_commit']}`; [catalog](https://github.com/asreview/synergy-dataset/blob/{output['synergy_commit']}/datasets.toml).",'- Local source files and SHA256 fingerprints are retained under data/reference-audit and data_manifest/clinical-reference-audit.json.','- Source-query generation, metadata retrieval and clinical LLM evaluation remain subsequent stages; this report does not claim their completion.']
 (BASE/'reports/clinical-reference-audit.md').write_text('\n'.join(lines)+'\n');print(json.dumps([{k:v for k,v in r.items() if k!='labels'} for r in records],indent=2))
if __name__=='__main__':main()
